WIDTH = 40
HP = 32
HK = 3
MEMB = 8
LAYOUTS = [("TYX", ()), ("TXY", ()), ("TYX", (2,)), ("TYX", (3,))]
DILATE = [1, 1]
USE_MASK = True
POOLHEAD = False
ATTN = 2
HEADS = 4
GMLP = False
GMLP_MAX = 256
ORTHO = False


def to_grid(v, order, flips, T, Y, X):
    B = v.shape[0]
    if order == "TYX":
        g = v.reshape(B, T, Y, X)
