        g = self.glob(torch.cat([f.mean((2, 3)), f.amax((2, 3))], dim=1))
        if self.grid_ok:
            place = 0
            for k, (o, fl) in enumerate(LAYOUTS):
                place = place + from_grid(self.outs[k](h), o, fl)
            if self.use_pool:
                place = place + self.pool(f)
        else:
